R-REL-1 to R-REL-3): the files a release of a signed milestone tag
carries, for the F-Emulator app.

  release.py build --tag TAG --version X.Y.Z --commit SHA --src DIR
                   --build DIR --report REPORT.json --records-commit SHA
                   --record-tree SHA --fwtest-version "fwtest 0.6.0 (...)"
                   --out DIR
      DIR gets small-beeps-X.Y.Z.bin (the build's app.bin, byte for
      byte), release.json, small-beeps-X.Y.Z.fm1img (both in one file),
      small-beeps-X.Y.Z.spdx.json (an SPDX 2.3 SBOM) and SHA256SUMS.
      SRC is the tag's files (tools/reproduce --export-only), BUILD its
      tools/build.sh output, REPORT the tag's commit's test record
      (records/<commit>/report.json at RECORDS-COMMIT, whose tree hash
      for that folder is RECORD-TREE). Stops if the record is not PASS,
      is another commit's, or names other outputs than the build's.
  release.py verify DIR
      Checks a release folder: release.json against the format
      (config/release.schema.json), the image's size and SHA-256, the
      .fm1img's header, hash and contents, and SHA256SUMS.
  release.py validate RELEASE.json
  release.py unpack FILE.fm1img DIR
      Writes the release.json and the image an .fm1img holds.
  release.py selftest --build DIR --out DIR
      C-RELEASE: a release made twice from build DIR with a stand-in
      record (this tree's own files), byte for byte the same, verified.

Everything in it comes from its inputs: no clock, no host, no path. The
same tag, build and records commit give the same bytes (R-REL-1).
"""

import argparse
import hashlib
import json
import os
import re
import shutil
import struct
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCHEMA = os.path.join(ROOT, "config", "release.schema.json")
NAME = "small-beeps"
FORMAT = "small-beeps-release/1"
REPO = "https://github.com/japes98/small-beeps"
LOAD_ADDRESS = 0x02000000        # HW-1, HW-2: the code window, where the image starts and runs from
TARGETS = ["f-emulator-app"]

# The .fm1img container (docs/RELEASE-FORMAT.md): a 64-byte header, then
# release.json, zero padding to a multiple of 16, then the image.
MAGIC = b"FM1IMG\x1a\n"
CONTAINER_VERSION = 1
HEADER = struct.Struct("<8sIIIIII32s")    # 64 bytes
ALIGN = 16


def sha256(b):
    return hashlib.sha256(b).hexdigest()


def read(path):
    with open(path, "rb") as f:
        return f.read()


def dumps(obj):
    """The one JSON form every file here uses: sorted keys, two spaces,
    plain ASCII, a newline at the end."""
    return (json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=True) + "\n").encode("ascii")


# --- The format (a small JSON Schema subset, checked here) -------------------

def check_schema(value, schema, where="release.json"):
    """Problems of value against schema: type, const, enum, pattern,
    minimum, minLength, required, properties, additionalProperties,
    items, minItems. Enough for config/release.schema.json; no other
    keyword is allowed in it (so nothing it says goes unchecked)."""
    known = {"$schema", "$id", "title", "description", "type", "const", "enum", "pattern", "minimum",
             "minLength", "required", "properties", "additionalProperties", "items", "minItems"}
    unknown = set(schema) - known
    if unknown:
        return ["%s: the schema uses %s, which this check does not know" % (where, sorted(unknown))]
    p = []
    types = {"object": dict, "array": list, "string": str, "boolean": bool}
    t = schema.get("type")
    if t == "integer":
        if not isinstance(value, int) or isinstance(value, bool):
            return ["%s: not an integer" % where]
    elif t in types:
        if not isinstance(value, types[t]):
            return ["%s: not a %s" % (where, t)]
    elif t is not None:
        return ["%s: the schema's type %r is unknown" % (where, t)]
    if "const" in schema and value != schema["const"]:
        p.append("%s: %r, not %r" % (where, value, schema["const"]))
    if "enum" in schema and value not in schema["enum"]:
        p.append("%s: %r not one of %r" % (where, value, schema["enum"]))
    if "pattern" in schema and not re.search(schema["pattern"], value):
        p.append("%s: %r does not match %s" % (where, value, schema["pattern"]))
    if "minLength" in schema and len(value) < schema["minLength"]:
        p.append("%s: shorter than %d" % (where, schema["minLength"]))
    if "minimum" in schema and value < schema["minimum"]:
        p.append("%s: %r under %r" % (where, value, schema["minimum"]))
    if t == "object":
        for k in schema.get("required", []):
            if k not in value:
                p.append("%s: no %s" % (where, k))
        props = schema.get("properties", {})
        for k, v in value.items():
            if k in props:
                p += check_schema(v, props[k], "%s.%s" % (where, k))
            elif schema.get("additionalProperties", True) is False:
                p.append("%s: %s is not in the format" % (where, k))
    if t == "array":
        if len(value) < schema.get("minItems", 0):
            p.append("%s: fewer than %d items" % (where, schema["minItems"]))
        if "items" in schema:
            for i, v in enumerate(value):
                p += check_schema(v, schema["items"], "%s[%d]" % (where, i))
    return p


def validate(meta, schema_path=SCHEMA):
    with open(schema_path) as f:
        return check_schema(meta, json.load(f))


# --- The .fm1img container ------------------------------------------------

def pack(meta_bytes, image):
    """An .fm1img: the header, release.json's bytes, padding, the image.
    The header's SHA-256 covers everything after the header."""
    json_off = HEADER.size
    image_off = json_off + len(meta_bytes)
    image_off += (-image_off) % ALIGN
    body = meta_bytes + b"\0" * (image_off - json_off - len(meta_bytes)) + image
    head = HEADER.pack(MAGIC, CONTAINER_VERSION, HEADER.size, json_off, len(meta_bytes), image_off, len(image),
                       hashlib.sha256(body).digest())
    return head + body


def unpack(blob):
    """(release.json's bytes, the image) of an .fm1img; ValueError if it is
    not a well-formed one."""
    if len(blob) < HEADER.size:
        raise ValueError("shorter than its header")
    magic, ver, hlen, joff, jlen, ioff, ilen, digest = HEADER.unpack_from(blob)
    if magic != MAGIC:
        raise ValueError("not an .fm1img (magic)")
    if ver != CONTAINER_VERSION or hlen != HEADER.size:
        raise ValueError("container version %d, header %d bytes: not this format's" % (ver, hlen))
    if joff != hlen or ioff < joff + jlen or ioff % ALIGN or ioff + ilen != len(blob):
        raise ValueError("offsets and lengths do not fit the file")
    if any(blob[joff + jlen:ioff]):
        raise ValueError("padding not zero")
    if hashlib.sha256(blob[hlen:]).digest() != digest:
        raise ValueError("SHA-256 of the contents does not match the header's")
    return blob[joff:joff + jlen], blob[ioff:ioff + ilen]


# --- Making a release -----------------------------------------------------

def file_name(version, ext):
    return "%s-%s.%s" % (NAME, version, ext)


def sizes(build):
    with open(os.path.join(build, "app.size")) as f:
        return {k: int(v) for k, v in (l.split() for l in f if l.strip())}


def store_format(src):
    """The store's format version and region, from the tag's
    docs/STORE-FORMAT.md (its title and its region's line)."""
    with open(os.path.join(src, "docs", "STORE-FORMAT.md")) as f:
        text = f.read()
    v = re.search(r"^# The store's format, version (\d+)", text, re.M)
    r = re.search(r"Chip offsets `(0x[0-9A-Fa-f]+)` to `(0x[0-9A-Fa-f]+)`", text)
    if not v or not r:
        raise ValueError("docs/STORE-FORMAT.md: no version or region found")
    return {"format_version": int(v.group(1)), "region": "%s-%s" % (r.group(1).upper().replace("0X", "0x"),
                                                                   r.group(2).upper().replace("0X", "0x"))}


def check_record(report, commit, outputs):
    """Problems of a test record against the build it is to vouch for."""
    p = []
    if report.get("commit") != commit:
        p.append("the record is of %s, not %s" % (report.get("commit"), commit))
    if report.get("overall") != "PASS":
        p.append("the record's overall result is %s, not PASS" % report.get("overall"))
    for name in ("app.bin", "app.elf"):
        if report.get("outputs", {}).get(name) != outputs.get(name):
            p.append("%s: the build's SHA-256 %s, the record's %s (not reproduced)"
                     % (name, outputs.get(name), report.get("outputs", {}).get(name)))
    return p


def metadata(a, image, report, src, size):
    env = report.get("environment", {})
    fw = re.match(r"fwtest (\S+)", a.fwtest_version)
    return {
        "format": FORMAT,
        "name": NAME,
        "version": a.version,
        "tag": a.tag,
        "git_commit": a.commit,
        "targets": TARGETS,
        "image": {
            "file": file_name(a.version, "bin"),
            "size": len(image),
            "sha256": sha256(image),
            "load_address": "0x%08X" % LOAD_ADDRESS,
            "entry": "0x%08X" % LOAD_ADDRESS,
            "ram_used": size["data"] + size["bss"] + size["stack"] + size["irq_stack"],
        },
        "fwtest": {
            "version": fw.group(1) if fw else a.fwtest_version,
            "build": a.fwtest_version,
            "image": env.get("fwtest_image", ""),
        },
        "record": {
            "path": "records/%s/" % a.commit,
            "records_commit": a.records_commit,
            "tree": a.record_tree,
            "overall": report.get("overall"),
        },
        "build": {
            "container": env.get("build_image_tag", ""),
            "toolchain_sha256": toolchain_sha256(src),
        },
        "store": store_format(src),
    }


def toolchain_sha256(src):
    with open(os.path.join(src, "tools", "Dockerfile")) as f:
        m = re.search(r"TOOLCHAIN_SHA256=([0-9a-f]{64})", f.read())
    return m.group(1) if m else ""


def sbom(meta, src):
    """An SPDX 2.3 SBOM: the firmware, the SDK headers it is built with,
    the toolchain (a build tool), and every source file of the image.
    Its time is the tag's commit's (--created), so it is reproducible."""
    files = []
    for top in ("firmware/app.ld", "firmware/src"):
        p = os.path.join(src, top)
        names = [top] if os.path.isfile(p) else sorted(top + "/" + n for n in os.listdir(p))
        files += [n for n in names if os.path.isfile(os.path.join(src, n))]
    sdk = None
    srcmd = os.path.join(src, "vendor", "jieli-sdk", "SOURCE.md")
    if os.path.exists(srcmd):
        with open(srcmd) as f:
            m = re.search(r"Commit: `([0-9a-f]{40})`", f.read())
        sdk = m.group(1) if m else None
    commit = meta["git_commit"]
    pk = [{
        "SPDXID": "SPDXRef-small-beeps", "name": NAME,
        "versionInfo": "%s (%s, %s)" % (meta["version"], meta["tag"], commit),
        "downloadLocation": "git+%s@%s" % (REPO, commit), "filesAnalyzed": False,
        "licenseConcluded": "MIT", "licenseDeclared": "MIT", "copyrightText": "Copyright (c) 2026 japes98",
        "primaryPackagePurpose": "FIRMWARE",
        "checksums": [{"algorithm": "SHA256", "checksumValue": meta["image"]["sha256"]}],
    }]
    if sdk:
        pk.append({
            "SPDXID": "SPDXRef-ac79-sdk", "name": "fw-AC79_AIoT_SDK (register-definition headers)",
            "versionInfo": sdk, "downloadLocation": "git+https://gitee.com/Jieli-Tech/fw-AC79_AIoT_SDK@" + sdk,
            "filesAnalyzed": False, "licenseConcluded": "Apache-2.0", "licenseDeclared": "Apache-2.0",
            "copyrightText": "Copyright JIELI (as stated in the files' headers)", "primaryPackagePurpose": "SOURCE"})
    if meta["build"]["toolchain_sha256"]:
        pk.append({
            "SPDXID": "SPDXRef-toolchain", "name": "jieli-linux-toolchains", "filesAnalyzed": False,
            "downloadLocation": "NOASSERTION",
            "checksums": [{"algorithm": "SHA256", "checksumValue": meta["build"]["toolchain_sha256"]}],
            "licenseConcluded": "NOASSERTION", "licenseDeclared": "NOASSERTION", "copyrightText": "NOASSERTION",
            "comment": "Build tool only; not in the image (docs/TOOLCHAIN.md).", "primaryPackagePurpose": "APPLICATION"})
    fl = []
    for i, n in enumerate(files):
        fl.append({"SPDXID": "SPDXRef-src-%d" % i, "fileName": "./" + n,
                   "checksums": [{"algorithm": "SHA256", "checksumValue": sha256(read(os.path.join(src, n)))}],
                   "licenseConcluded": "MIT", "licenseInfoInFiles": ["MIT"],
                   "copyrightText": "Copyright (c) 2026 japes98"})
    rel = [{"spdxElementId": "SPDXRef-DOCUMENT", "relationshipType": "DESCRIBES",
            "relatedSpdxElement": "SPDXRef-small-beeps"}]
    rel += [{"spdxElementId": "SPDXRef-small-beeps", "relationshipType": "CONTAINS",
             "relatedSpdxElement": f["SPDXID"]} for f in fl]
    if sdk:
        rel.append({"spdxElementId": "SPDXRef-small-beeps", "relationshipType": "DEPENDS_ON",
                    "relatedSpdxElement": "SPDXRef-ac79-sdk"})
    return {
        "spdxVersion": "SPDX-2.3", "dataLicense": "CC0-1.0", "SPDXID": "SPDXRef-DOCUMENT",
        "name": "%s %s" % (NAME, meta["version"]),
        "documentNamespace": "%s/releases/%s/sbom/%s" % (REPO, meta["tag"], commit),
        "creationInfo": {"created": meta_created(meta), "creators": ["Tool: tools/release.py"]},
        "packages": pk, "files": fl, "relationships": rel,
    }


_CREATED = {}


def meta_created(meta):
    return _CREATED.get(meta["git_commit"], "1970-01-01T00:00:00Z")


def sums(names_bytes):
    return "".join("%s  %s\n" % (sha256(b), n) for n, b in sorted(names_bytes.items())).encode("ascii")


def build(a):
    image = read(os.path.join(a.build, "app.bin"))
    outputs = {n: sha256(read(os.path.join(a.build, n))) for n in ("app.bin", "app.elf")}
    with open(a.report) as f:
        report = json.load(f)
    problems = check_record(report, a.commit, outputs)
    if not re.match(r"^\d+\.\d+\.\d+$", a.version):
        problems.append("version %r is not X.Y.Z" % a.version)
    if problems:
        return problems
    meta = metadata(a, image, report, a.src, sizes(a.build))
    problems = validate(meta)
    if problems:
        return problems
    _CREATED[a.commit] = a.created
    mb = dumps(meta)
    files = {
        file_name(a.version, "bin"): image,
        "release.json": mb,
        file_name(a.version, "fm1img"): pack(mb, image),
        file_name(a.version, "spdx.json"): dumps(sbom(meta, a.src)),
    }
    os.makedirs(a.out, exist_ok=True)
    files["SHA256SUMS"] = sums(files)
    for n, b in files.items():
        with open(os.path.join(a.out, n), "wb") as f:
            f.write(b)
    return []


def verify(d):
    """Problems of a release folder (R-REL-1, R-REL-2)."""
    p = []
    try:
        mb = read(os.path.join(d, "release.json"))
        meta = json.loads(mb)
    except (OSError, ValueError) as e:
        return ["release.json: %s" % e]
    p += validate(meta)
    if p:
        return p
    img_path = os.path.join(d, meta["image"]["file"])
    try:
        image = read(img_path)
    except OSError:
        return ["no %s" % meta["image"]["file"]]
    if len(image) != meta["image"]["size"] or sha256(image) != meta["image"]["sha256"]:
        p.append("%s: size %d, SHA-256 %s; release.json says %d, %s"
                 % (meta["image"]["file"], len(image), sha256(image), meta["image"]["size"], meta["image"]["sha256"]))
    fm = os.path.join(d, file_name(meta["version"], "fm1img"))
    try:
        jb, ib = unpack(read(fm))
        if jb != mb or ib != image:
            p.append("%s: holds another release.json or image than the folder's" % os.path.basename(fm))
    except (OSError, ValueError) as e:
        p.append("%s: %s" % (os.path.basename(fm), e))
    try:
        listed = {}
        for line in read(os.path.join(d, "SHA256SUMS")).decode("ascii").splitlines():
            h, n = line.split("  ", 1)
            listed[n] = h
    except (OSError, ValueError) as e:
        return p + ["SHA256SUMS: %s" % e]
    present = sorted(n for n in os.listdir(d) if n != "SHA256SUMS")
    if sorted(listed) != present:
        p.append("SHA256SUMS lists %s; the folder holds %s" % (sorted(listed), present))
    for n, h in listed.items():
        if os.path.exists(os.path.join(d, n)) and sha256(read(os.path.join(d, n))) != h:
            p.append("SHA256SUMS: %s does not match" % n)
    return p


def same_tree(a, b):
    na, nb = sorted(os.listdir(a)), sorted(os.listdir(b))
    if na != nb:
        return ["the two releases hold %s and %s" % (na, nb)]
    return ["%s differs between the two" % n for n in na if read(os.path.join(a, n)) != read(os.path.join(b, n))]


def selftest(a):
    """C-RELEASE: from build A, with a stand-in record of its outputs."""
    out = os.path.abspath(a.out)
    shutil.rmtree(out, ignore_errors=True)
    os.makedirs(out)
    report = {"commit": "0" * 40, "overall": "PASS",
              "outputs": {n: sha256(read(os.path.join(a.build, n))) for n in ("app.bin", "app.elf")},
              "environment": {"fwtest_image": "selftest", "build_image_tag": "selftest"}}
    rp = os.path.join(out, "report.json")
    with open(rp, "wb") as f:
        f.write(dumps(report))
    p = []
    for k in ("a", "b"):
        ns = argparse.Namespace(tag="m0", version="0.0.0", commit="0" * 40, src=ROOT, build=a.build, report=rp,
                                records_commit="0" * 40, record_tree="0" * 40, fwtest_version="fwtest 0.0.0 (selftest)",
                                created="1970-01-01T00:00:00Z", out=os.path.join(out, k))
        p += ["build %s: %s" % (k, q) for q in build(ns)]
    if not p:
        p += same_tree(os.path.join(out, "a"), os.path.join(out, "b"))
        p += verify(os.path.join(out, "a"))
        m = json.loads(read(os.path.join(out, "a", "release.json")))
        if read(os.path.join(out, "a", m["image"]["file"])) != read(os.path.join(a.build, "app.bin")):
            p.append("the release's image is not build A's app.bin")
    for q in p:
        print("FAIL: " + q)
    print("release selftest: %s" % ("FAIL" if p else "PASS (built twice, byte for byte the same; verified)"))
    return 1 if p else 0


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
    b = sub.add_parser("build")
    for k in ("tag", "version", "commit", "src", "build", "report", "records-commit", "record-tree",
              "fwtest-version", "created", "out"):
        b.add_argument("--" + k, required=k != "created", default="1970-01-01T00:00:00Z" if k == "created" else None)
    v = sub.add_parser("verify")
    v.add_argument("dir")
    va = sub.add_parser("validate")
    va.add_argument("json")
    u = sub.add_parser("unpack")
    u.add_argument("file")
    u.add_argument("dir")
    s = sub.add_parser("selftest")
    s.add_argument("--build", required=True)
    s.add_argument("--out", required=True)
    a = ap.parse_args()
    if a.cmd == "build":
        p = build(a)
    elif a.cmd == "verify":
        p = verify(a.dir)
    elif a.cmd == "validate":
        with open(a.json) as f:
            p = validate(json.load(f))
    elif a.cmd == "unpack":
        jb, ib = unpack(read(a.file))
        meta = json.loads(jb)
        os.makedirs(a.dir, exist_ok=True)
        for n, data in (("release.json", jb), (meta["image"]["file"], ib)):
            with open(os.path.join(a.dir, n), "wb") as f:
                f.write(data)
        p = []
    else:
        return selftest(a)
    for q in p:
        print("FAIL: " + q)
    print("release %s: %s" % (a.cmd, "FAIL" if p else "OK"))
    return 1 if p else 0


if __name__ == "__main__":
    sys.exit(main())

